import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    queries = input_data[1:]

    pattern = "Yes" * 20
    results = []

    for i in range(t):
        s = queries[i]
        if s in pattern:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
